## Why This Is Asked
Tests cross-language async design, memory ownership, and error propagation in CGO.

## Key Concepts
- CGO callbacks from C to Go and lifetime guarantees
- Correctly freeing C-allocated strings from Go
- Streaming results via channels with backpressure and cancellation
- Robust error propagation across language boundaries

## Code Example
```c
// header: cgob_blocks.h
void process_blocks_async(const void** blocks, const size_t* lengths, size_t n, void(*cb)(size_t idx, const char* json, void* user), void* user);
```
```go
// binding.go
package main

/*
#include "cgob_blocks.h"
#include <stdlib.h>

typedef struct {
    size_t idx;
    const char* json;
} CallbackData;

extern void goCallback(size_t idx, const char* json, void* user);

static void cgo_callback_wrapper(size_t idx, const char* json, void* user) {
    goCallback(idx, json, user);
}

static void process_blocks_wrapper(const void** blocks, const size_t* lengths, size_t n, void* user) {
    process_blocks_async(blocks, lengths, n, cgo_callback_wrapper, user);
}
*/
import "C"
import (
    "context"
    "sync"
    "unsafe"
)

type result struct {
    idx  int
       json string
    err  error
}

func DispatchBlocks(blocks [][]byte) (<-chan string, error) {
    if len(blocks) == 0 {
        return nil, nil
    }

    n := len(blocks)
    cBlocks := make([]*C.void, n)
    cLengths := make([]C.size_t, n)

    for i, block := range blocks {
        if len(block) > 0 {
            cBlocks[i] = unsafe.Pointer(&block[0])
        }
        cLengths[i] = C.size_t(len(block))
    }

    ctx, cancel := context.WithCancel(context.Background())
    results := make(chan string, n)
    errCh := make(chan error, 1)

    var wg sync.WaitGroup
    wg.Add(1)

    go func() {
        defer wg.Done()
        defer close(results)

        C.process_blocks_wrapper(
            &cBlocks[0],
            &cLengths[0],
            C.size_t(n),
            unsafe.Pointer(&resultCtx{ctx: ctx, results: results, cancel: cancel}),
        )
    }()

    go func() {
        wg.Wait()
        close(errCh)
    }()

    return results, nil
}

type resultCtx struct {
    ctx    context.Context
    results chan<- string
    cancel context.CancelFunc
}

//export goCallback
func goCallback(idx C.size_t, json *C.char, user unsafe.Pointer) {
    ctxPtr := (*resultCtx)(user)

    if ctxPtr.ctx.Err() != nil {
        return
    }

    if json == nil {
        return
    }

    result := C.GoString(json)
    C.free(unsafe.Pointer(json))

    select {
    case ctxPtr.results <- result:
    case <-ctxPtr.ctx.Done():
        ctxPtr.cancel()
    }
}
```

## Key Design Decisions

1. **Pointer Handling**: Blocks are passed as array of pointers with their lengths, maintaining zero-copy semantics from Go to C

2. **Memory Ownership**: C-allocated JSON strings are freed via C.free after converting to Go string, ensuring no memory leaks

3. **Cancellation**: Context cancellation enables early termination; callback checks ctx.Err() before sending

4. **Backpressure**: Buffered channel (size n) prevents unbounded memory growth

5. **Thread Safety**: sync.WaitGroup ensures proper cleanup before function return

## Why This Is Asked
This question tests the ability to bridge Go closures to C, manage memory safely across the language boundary, and implement concurrent multi-batch processing with CGO while keeping the Go garbage collector safe.

## Key Concepts
- **CGO callback bridge**: Using `cgo.Handle` to safely store and invoke Go closures from C
- **Pointer safety**: Passing Go pointers to C without violating CGO safety rules
- **Memory lifecycle**: Allocating C strings, sorting in place, and freeing all allocations appropriately
- **Concurrency**: Worker pool pattern for processing multiple batches

## Solution

### header.h
```c
#ifndef SORT_STRINGS_H
#define SORT_STRINGS_H

#include <stddef.h>

int sort_strings(char** in_out, size_t n, 
    int (*cmp)(const char*, const char*, void*), 
    void* ctx);

#endif
```

### sort_strings.c
```c
#include "header.h"
#include <stdlib.h>
#include <string.h>

static void swap(char** a, char** b) {
    char* tmp = *a;
    *a = *b;
    *b = tmp;
}

int sort_strings(char** in_out, size_t n, 
    int (*cmp)(const char*, const char*, void*), 
    void* ctx) {
    if (!in_out || n == 0 || !cmp) return -1;

    for (size_t i = 0; i < n - 1; i++) {
        for (size_t j = 0; j < n - i - 1; j++) {
            int result = cmp(in_out[j], in_out[j + 1], ctx);
            if (result > 0) {
                swap(&in_out[j], &in_out[j + 1]);
            }
        }
    }
    return 0;
}
```

### sort_wrapper.go
```go
package main

/*
#include "header.h"
#include <stdlib.h>

typedef int (*CmpFn)(const char*, const char*, void*);

static int wrapper_cmp(const char* a, const char* b, void* ctx) {
    // This is a placeholder; actual invocation happens via CGO
    return 0;
}
*/
import "C"
import (
	"fmt"
	"runtime"
	"sync"
	"unsafe"
)

type sortHandle C.int

var handleStore = struct {
	sync.RWMutex
	m map[sortHandle]func(string, string) int
}{
m: make(map[sortHandle]func(string, string) int)}

//export goCmpCallback
func goCmpCallback(a, b *C.char, ctx unsafe.Pointer) C.int {
	handle := sortHandle(uintptr(ctx))
	handleStore.RLock()
	cmpFn := handleStore.m[handle]
	handleStore.RUnlock()

	if cmpFn == nil {
		return 0
	}
	return C.int(cmpFn(C.GoString(a), C.GoString(b)))
}

func SortStringsWithComparator(vals []string, cmp func(string, string) int) ([]string, error) {
	if cmp == nil {
		return nil, fmt.Errorf("comparator cannot be nil")
	}

	handle := sortHandle(runtime.NewCString("")) // dummy allocation for unique handle
	handleStore.Lock()
	handleStore.m[handle] = cmp
	handleStore.Unlock()

	cStrs := make([]*C.char, len(vals))
	for i, v := range vals {
		cStrs[i] = C.CString(v)
	}

	result := C.sort_strings(&cStrs[0], C.size_t(len(cStrs)),
		(C.CmpFn)(C.wrapper_cmp), unsafe.Pointer(uintptr(handle)))

	for i := range cStrs {
		C.free(unsafe.Pointer(cStrs[i]))
	}

	handleStore.Lock()
	delete(handleStore.m, handle)
	handleStore.Unlock()

	if result != 0 {
		return nil, fmt.Errorf("sort failed with code %d", result)
	}

	resultVals := make([]string, len(vals))
	for i, cs := range cStrs {
		resultVals[i] = C.GoString(cs)
	}
	return resultVals, nil
}
```

### worker_pool.go
```go
package main

import (
	"context"
	"sync"
)

type Job struct {
	ID    int
	Input []string
}

type WorkerPool struct {
	workers   int
	jobs      chan Job
	results   chan []string
	errors    chan error
	wg        sync.WaitGroup
}

func NewWorkerPool(workers int, bufSize int) *WorkerPool {
	return &WorkerPool{
		workers: workers,
		jobs:    make(chan Job, bufSize),
		results: make(chan []string, bufSize),
		errors:  make(chan error, bufSize),
	}
}

func (p *WorkerPool) Start(ctx context.Context, cmp func(string, string) int) {
	for i := 0; i < p.workers; i++ {
		p.wg.Add(1)
		go p.worker(ctx, cmp)
	}
}

func (p *WorkerPool) worker(ctx context.Context, cmp func(string, string) int) {
	defer p.wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case job, ok := <-p.jobs:
			if !ok {
				return
			}
			result, err := SortStringsWithComparator(job.Input, cmp)
			if err != nil {
				p.errors <- err
			} else {
				p.results <- result
			}
		}
	}
}

func (p *WorkerPool) Submit(job Job) {
	p.jobs <- job
}

func (p *WorkerPool) Close() {
	close(p.jobs)
	p.wg.Wait()
	close(p.results)
	close(p.errors)
}
```

